<script lang="ts">
 import Activity from '$lib/Activity.svelte';
 import Scoreboard from '$lib/Scoreboard.svelte';
 import Exercises from '$lib/Exercises.svelte';
 import Status from '$lib/Status.svelte';
 import {onMount} from 'svelte';import {Calendar,Clock,Play,Plus,Trash2,GitBranch,Users} from '@lucide/svelte';import Guard from '$lib/Guard.svelte';import Notice from '$lib/Notice.svelte';import {api,adminView,refreshAdmin,date} from '$lib/api';let data=$derived($adminView);let error=$state('');let busy=$state(false);let name=$state('Example Branch practice');let template=$state('');let hours=$state(4);let teamCount=$state(5);let capacity=$state(6);let extension=$state(1);
 const readyCount=$derived(data?.teams.filter(t=>t.status==='ready').length??0);
 const failedCount=$derived(data?.teams.filter(t=>t.status==='failed').length??0);
 const preparing=$derived(data?.jobs.some(j=>j.kind==='prepare'&&['queued','running'].includes(j.status))??false);
 const remainingHours=$derived(data?.meeting?Math.max(0,Math.floor((Date.parse(data.meeting.created)+8*3600000-Date.parse(data.meeting.expires))/3600000)):0);
 $effect(()=>{if(remainingHours>0&&extension>remainingHours)extension=remainingHours});let confirmation:HTMLDialogElement;let action=$state('');
 async function load(){try{await refreshAdmin();if(!template)template=$adminView?.templates.find(t=>t.built)?.id??''}catch(e){error=(e as Error).message}}
 onMount(()=>{void load();const t=setInterval(load,2000);return()=>clearInterval(t)});
 async function run(path:string,body:unknown={}){busy=true;error='';try{await api(path,body);confirmation?.close();await load()}catch(e){error=(e as Error).message}finally{busy=false}}
 function confirm(which:string){action=which;confirmation.showModal()}
</script>
<svelte:head><title>Manage meeting · LabCentral</title></svelte:head>
<div class="flex flex-wrap items-start justify-between gap-5"><div><h1 class="text-3xl font-semibold tracking-tight sm:text-4xl">Manage meeting</h1></div><a href="/admin/templates/" class="btn btn-sm min-h-11"><GitBranch size={16}/>Templates</a></div>
<Guard admin><Notice message={error}/>{#if data}
{#if !data.meeting||data.meeting.status==='ended'}<form class="mt-10 max-w-xl" onsubmit={(e)=>{e.preventDefault();void run('/api/admin/meeting',{name,template,hours,teamCount,capacity})}}><fieldset class="fieldset"><legend class="fieldset-legend text-lg">Create a meeting</legend><label class="label" for="meeting-name">Meeting name</label><input class="input w-full" id="meeting-name" bind:value={name} maxlength="100" required/><label class="label mt-3" for="template">Built template revision</label><select id="template" class="select w-full" bind:value={template} required><option value="" disabled>Choose a built revision</option>{#each data.templates.filter(t=>t.built) as t}<option value={t.id}>{t.name} · {t.commit.slice(0,7)}</option>{/each}</select><div class="mt-3 grid gap-4 sm:grid-cols-3">
 <div><label class="label mb-2" for="team-count">Number of teams</label><input id="team-count" class="input w-full" type="number" min="1" max="100" step="1" bind:value={teamCount} required aria-describedby="team-count-help"/><p id="team-count-help" class="mt-2 text-xs text-base-content/75">1–100 teams</p></div>
 <div><label class="label mb-2" for="capacity">Students per team</label><input id="capacity" class="input w-full" type="number" min="1" max="100" step="1" bind:value={capacity} required aria-describedby="capacity-help"/><p id="capacity-help" class="mt-2 text-xs text-base-content/75">1–100 students</p></div>
 <div><label class="label mb-2" for="duration">Duration (hours)</label><input id="duration" class="input w-full" type="number" min="1" max="8" step="1" bind:value={hours} required aria-describedby="duration-help"/><p id="duration-help" class="mt-2 text-xs text-base-content/75">1–8 hours</p></div>
 </div><p class="mt-4 text-sm text-base-content/75">{(teamCount||0)*(capacity||0)} student places. Machines and files are deleted automatically when the meeting ends.</p><button disabled={busy||!template} class="btn btn-primary mt-5"><Plus size={17}/>Create meeting</button></fieldset></form>{#if !data.templates.some(t=>t.built)}<p class="mt-5 text-sm">First, <a class="link" href="/admin/templates/">build a template</a>.</p>{/if}
{:else}<section class="mt-10 border-y border-base-300 py-6"><div class="flex flex-wrap items-start justify-between gap-5"><div><h2 class="flex items-center gap-3 text-2xl font-semibold"><Calendar size={22}/>{data.meeting.name}</h2><p class="mt-3 flex items-center gap-2 text-sm text-base-content/75"><Clock size={16}/>Cleanup at {date(data.meeting.expires)}<Status status={data.meeting.status}/></p><p class="mt-2 text-sm text-base-content/75">{readyCount} / {data.teams.length} labs ready · {data.teams.reduce((total,team)=>total+team.capacity,0)} student places</p>{#if failedCount}<p class="mt-2 flex items-center gap-2 text-sm text-error"><Status status="failed"/>{failedCount} {failedCount===1?'lab needs':'labs need'} attention. <a class="link" href="#activity-title">View activity</a></p>{/if}</div><div class="flex flex-wrap gap-2">{#if data.meeting.status!=='ending'}{#if remainingHours>0}<div class="flex items-center gap-2"><label class="sr-only" for="extension">Extend by</label><select id="extension" class="select select-sm w-28" bind:value={extension} disabled={busy}>{#each Array.from({length:remainingHours},(_,i)=>i+1) as amount}<option value={amount}>{amount} {amount===1?'hour':'hours'}</option>{/each}</select><button type="button" class="btn btn-sm min-h-11" disabled={busy} onclick={()=>run('/api/admin/extend',{hours:extension})}><Plus size={16}/>Add time</button></div>{:else}<span class="self-center text-sm text-base-content/75">Eight-hour limit reached</span>{/if}<button class="btn btn-sm min-h-11 btn-primary" disabled={busy||readyCount===data.teams.length||preparing} onclick={()=>confirm('prepare')}><Play size={16}/>Prepare labs</button><button type="button" class="btn btn-sm min-h-11 btn-error btn-outline sm:ml-3" disabled={busy} onclick={()=>confirm('end')}><Trash2 size={16}/>End meeting</button>{/if}</div></div>{#if readyCount===data.teams.length}<p class="mt-3 text-sm text-base-content/75">All team labs are prepared.</p>{:else if preparing}<p class="mt-3 text-sm text-base-content/75">Preparation is running. Ready teams can use their labs.</p>{/if}</section>
 <div class="mt-7 max-w-full overflow-x-auto"><table class="table table-sm"><thead><tr><th>Team</th><th>Members</th><th>Lab</th></tr></thead><tbody>{#each data.teams as team}<tr><th><span class="flex items-center gap-2"><Users size={16}/>{team.name}</span></th><td>{team.members} / {team.capacity}</td><td><Status status={team.status}/></td></tr>{/each}</tbody></table></div>{/if}
 <Scoreboard {data} onchange={load}/>
 <Exercises {data} onchange={load}/>
 <Activity {data} onchange={refreshAdmin}/>
{/if}</Guard>
<dialog bind:this={confirmation} class="modal" aria-labelledby="confirm-title"><div class="modal-box"><h2 id="confirm-title" class="text-xl font-semibold">{action==='end'?'End this meeting?':'Prepare the team labs?'}</h2><p class="mt-4 leading-relaxed">{action==='end'?`This deletes all ${data?.teams.length??0} team labs, including their machines and workspace files. This cannot be undone.`:`This provisions the selected template for ${data?.teams.length??0} teams. Cloud compute, storage, public addresses, and transfer incur charges. Machines and files are deleted at the meeting deadline.`}</p><Notice message={error}/><div class="modal-action"><form method="dialog"><button class="btn btn-sm min-h-11">Cancel</button></form><button class="btn btn-sm min-h-11" class:btn-error={action==='end'} class:btn-primary={action==='prepare'} disabled={busy} onclick={()=>run('/api/admin/'+action)}>{action==='end'?'Delete team labs':'Prepare labs'}</button></div></div></dialog>
